{"results": [{"id": "hp_doc_43002e9cfe7a8bd78944e893c7cfa3f762251572526a0abc5d5d6fe4269fd4da", "title": "The Autobiography of Alice B. Toklas", "text": "The Autobiography of Alice B. Toklas is a 1933 book by Gertrude Stein, written in the guise of an autobiography authored by Alice B. Toklas, her life partner. In 1998, Modern Library ranked it as one of the 20 greatest English-language nonfiction books of the 20th century.", "score": 36.0902}, {"id": "hp_doc_dd383e69a6ba28208d3eed27c2d6033d70e5183d476ae1dc4ba787bf35ff7f4b", "title": "The Alice B. Toklas Cookbook", "text": "The Alice B. Toklas Cook Book, first published in 1954, is one of the bestselling cookbooks of all time. Alice B. Toklas, writer Gertrude Stein's life partner, wrote the book to make up for her unwillingness at the time to write her memoirs, in deference to Stein's 1933 book, \"The Autobiography of Alice B. Toklas\".", "score": 33.7228}, {"id": "hp_doc_6ba6f21f07bda0bbf1011c92ebdd491ae341d17266fd24a6c6ffefc31608b343", "title": "Alice B. Toklas LGBT Democratic Club", "text": "The Alice B. Toklas LGBT Democratic Club (first known as The Alice B. Toklas Memorial Democratic Club) is a San Francisco-based association and political action committee for lesbian, gay, bisexual, and transgender (LGBT) Democrats.", "score": 26.7361}], "remaining_searches": 2}
